import time
import board
import digitalio
import pwmio
import analogio
import busio
import usb_cdc

try:
    import neopixel
except Exception:
    neopixel = None

print("CP_IO_BOOT")
led = digitalio.DigitalInOut(board.GP16)
led.direction = digitalio.Direction.OUTPUT
servo = pwmio.PWMOut(board.GP15, frequency=50, duty_cycle=0)
pixels = None
if neopixel is not None:
    try:
        pixels = neopixel.NeoPixel(board.GP2, 1, auto_write=False)
    except Exception as exc:
        print("CP_IO_NEO_INIT_ERR", exc)
pot = None
buzz = None
i2c = None
try:
    pot = analogio.AnalogIn(board.GP26)
except Exception as exc:
    print("CP_IO_POT_INIT_ERR", exc)
try:
    buzz = pwmio.PWMOut(board.GP18, frequency=1800, duty_cycle=0)
except Exception as exc:
    print("CP_IO_BUZZ_INIT_ERR", exc)
try:
    i2c = busio.I2C(board.GP5, board.GP4, frequency=400000)
except Exception as exc:
    print("CP_IO_I2C_INIT_ERR", exc)

def clamp_u16(value):
    return max(0, min(65535, int(value)))

def set_servo_angle(angle):
    angle = max(0, min(180, int(angle)))
    pulse_us = 500 + int((angle * 2000) / 180)
    duty = int((pulse_us * 65535) / 20000)
    servo.duty_cycle = clamp_u16(duty)

def i2c_write(payload):
    if i2c is None:
        return False
    deadline = time.monotonic() + 0.05
    while not i2c.try_lock():
        if time.monotonic() >= deadline:
            return False
    try:
        i2c.writeto(0x3C, bytes(payload))
        return True
    except Exception as exc:
        print("CP_IO_OLED_ERR", exc)
        return False
    finally:
        i2c.unlock()

def oled_cmd(cmd):
    return i2c_write((0x00, cmd & 0xFF))

def oled_data(data):
    return i2c_write(bytes([0x40]) + bytes(data))

def oled_init():
    ok = True
    for cmd in (0xAE, 0x20, 0x00, 0x21, 0x00, 0x7F, 0x22, 0x00, 0x07, 0xAF):
        ok = oled_cmd(cmd) and ok
    return ok

oled_init_ok = oled_init()
print("CP_IO_OLED_INIT", 1 if oled_init_ok else 0)

for i in range(10):
    on = (i % 2) == 0
    led.value = on
    angle = (i * 20) % 181
    set_servo_angle(angle)
    if buzz is not None:
        buzz.frequency = 1400 + (i * 80)
        buzz.duty_cycle = 32000 if on else 0
    if pixels is not None:
        pixels[0] = ((32 + (i * 18)) & 0xFF, 8 if on else 2, 24 if on else 96)
        pixels.show()
    pot_value = pot.value if pot is not None else -1
    pattern = 0xAA if on else 0x55
    oled_ok = oled_cmd(0xB0 + (i % 8))
    oled_ok = oled_cmd(0x00) and oled_ok
    oled_ok = oled_cmd(0x10) and oled_ok
    oled_ok = oled_data(bytes([pattern]) * 16) and oled_ok
    print("CP_IO_STEP", i, "POT", pot_value, "ANGLE", angle, "OLED", 1 if oled_ok else 0)
    time.sleep(0.08)

print("CP_IO_READY")
deadline = time.monotonic() + 2.5
received = ""
console = getattr(usb_cdc, "console", None)
while time.monotonic() < deadline:
    waiting = int((console.in_waiting if console is not None else 0) or 0)
    if waiting:
        raw = console.read(waiting) or b""
        text = raw.decode("utf-8", "ignore").strip()
        if text:
            received = text
            print("CP_IO_RX", text)
            if console is not None:
                console.write(("CP_IO_ECHO:" + text + "\n").encode("utf-8"))
            break
    time.sleep(0.05)

print("CP_IO_DONE")

